-- Prometeo DataGrip test fixture for Oracle Database 23ai (schema DEMO). Idempotent.
-- Statements end with ';', PL/SQL units and blocks with a line holding only '/'.

BEGIN
    FOR o IN (
        SELECT * FROM (
            SELECT 'VIEW' t, 'V_ORDER_TOTALS' n FROM dual UNION ALL
            SELECT 'MATERIALIZED VIEW', 'MV_SALES_BY_CATEGORY' FROM dual UNION ALL
            SELECT 'SYNONYM', 'SYN_PRODUCTS' FROM dual UNION ALL
            SELECT 'SEQUENCE', 'SEQ_INVOICE' FROM dual UNION ALL
            SELECT 'PROCEDURE', 'RESTOCK' FROM dual UNION ALL
            SELECT 'FUNCTION', 'ORDER_TOTAL' FROM dual UNION ALL
            SELECT 'PACKAGE', 'PKG_SHOP' FROM dual UNION ALL
            SELECT 'TABLE', x FROM (
                SELECT column_value x FROM TABLE(sys.odcivarchar2list(
                    'ORDER_ITEMS', 'ORDERS', 'CUSTOMERS', 'PRODUCTS', 'CATEGORIES', 'ALL_TYPES', 'BIG_TABLE', 'NO_PK_TABLE')))
        )
    ) LOOP
        BEGIN
            EXECUTE IMMEDIATE 'DROP ' || o.t || ' "' || o.n || '"' ||
                CASE o.t WHEN 'TABLE' THEN ' CASCADE CONSTRAINTS PURGE' ELSE '' END;
        EXCEPTION WHEN OTHERS THEN NULL;
        END;
    END LOOP;
END;
/

CREATE TABLE categories (
    id        NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    name      VARCHAR2(100) NOT NULL,
    parent_id NUMBER,
    CONSTRAINT uq_categories_name UNIQUE (name),
    CONSTRAINT fk_categories_parent FOREIGN KEY (parent_id) REFERENCES categories (id) ON DELETE SET NULL
);
COMMENT ON TABLE categories IS 'Product categories';
COMMENT ON COLUMN categories.name IS 'Display name';

CREATE TABLE products (
    id          NUMBER GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
    sku         VARCHAR2(32) NOT NULL,
    name        VARCHAR2(255) NOT NULL,
    category_id NUMBER NOT NULL,
    price       NUMBER(10, 2) NOT NULL,
    stock       NUMBER(9) DEFAULT 0 NOT NULL,
    tags        CLOB,
    created_at  TIMESTAMP DEFAULT SYSTIMESTAMP NOT NULL,
    updated_at  TIMESTAMP,
    CONSTRAINT uq_products_sku UNIQUE (sku),
    CONSTRAINT fk_products_category FOREIGN KEY (category_id) REFERENCES categories (id),
    CONSTRAINT products_price_positive CHECK (price > 0),
    CONSTRAINT products_tags_json CHECK (tags IS JSON)
);
CREATE INDEX idx_products_category ON products (category_id);
COMMENT ON COLUMN products.sku IS 'Stock keeping unit';

CREATE TABLE customers (
    id         NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    email      VARCHAR2(255) NOT NULL,
    name       VARCHAR2(255) NOT NULL,
    vip        NUMBER(1) DEFAULT 0 NOT NULL,
    created_at DATE DEFAULT SYSDATE NOT NULL,
    CONSTRAINT uq_customers_email UNIQUE (email),
    CONSTRAINT customers_vip_bool CHECK (vip IN (0, 1))
);

CREATE TABLE orders (
    id          NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    customer_id NUMBER NOT NULL,
    status      VARCHAR2(10) DEFAULT 'new' NOT NULL,
    placed_at   TIMESTAMP WITH TIME ZONE DEFAULT SYSTIMESTAMP NOT NULL,
    note        CLOB,
    CONSTRAINT fk_orders_customer FOREIGN KEY (customer_id) REFERENCES customers (id) ON DELETE CASCADE,
    CONSTRAINT orders_status_ck CHECK (status IN ('new', 'paid', 'shipped', 'cancelled'))
);
CREATE INDEX idx_orders_customer ON orders (customer_id);

CREATE TABLE order_items (
    order_id   NUMBER NOT NULL,
    line_no    NUMBER NOT NULL,
    product_id NUMBER NOT NULL,
    qty        NUMBER NOT NULL,
    unit_price NUMBER(10, 2) NOT NULL,
    CONSTRAINT pk_order_items PRIMARY KEY (order_id, line_no),
    CONSTRAINT fk_items_order FOREIGN KEY (order_id) REFERENCES orders (id) ON DELETE CASCADE,
    CONSTRAINT fk_items_product FOREIGN KEY (product_id) REFERENCES products (id),
    CONSTRAINT items_qty_positive CHECK (qty > 0)
);

INSERT INTO categories (name, parent_id) VALUES ('Electronics', NULL);
INSERT INTO categories (name, parent_id) VALUES ('Books', NULL);
INSERT INTO categories (name, parent_id) VALUES ('Garden', NULL);
INSERT INTO categories (name, parent_id) VALUES ('Laptops', 1);
INSERT INTO categories (name, parent_id) VALUES ('Phones', 1);

INSERT INTO products (sku, name, category_id, price, stock, tags)
SELECT 'SKU-' || LPAD(n, 4, '0'), 'Product ' || n, 1 + MOD(n, 5), ROUND(5 + n * 3.37, 2), MOD(n * 7, 40),
       CASE WHEN MOD(n, 3) = 0 THEN '["sale","new"]' ELSE '["std"]' END
FROM (SELECT LEVEL n FROM dual CONNECT BY LEVEL <= 20);

INSERT INTO customers (email, name, vip)
SELECT 'customer' || n || '@example.com', 'Customer ' || n, CASE WHEN MOD(n, 4) = 0 THEN 1 ELSE 0 END
FROM (SELECT LEVEL n FROM dual CONNECT BY LEVEL <= 10);

INSERT INTO orders (customer_id, status, placed_at, note)
SELECT 1 + MOD(n, 10),
       CASE MOD(n, 4) WHEN 0 THEN 'new' WHEN 1 THEN 'paid' WHEN 2 THEN 'shipped' ELSE 'cancelled' END,
       TIMESTAMP '2024-01-01 10:00:00 +00:00' + n,
       CASE WHEN MOD(n, 5) = 0 THEN 'gift wrap' END
FROM (SELECT LEVEL n FROM dual CONNECT BY LEVEL <= 30);

INSERT INTO order_items (order_id, line_no, product_id, qty, unit_price)
SELECT o.n, l.n, 1 + MOD(o.n * 3 + l.n, 20), 1 + MOD(o.n + l.n, 4), ROUND(10 + o.n * 1.5 + l.n, 2)
FROM (SELECT LEVEL n FROM dual CONNECT BY LEVEL <= 30) o,
     (SELECT LEVEL n FROM dual CONNECT BY LEVEL <= 3) l;

COMMIT;

CREATE VIEW v_order_totals AS
SELECT o.id AS order_id, c.name AS customer, o.status, SUM(oi.qty * oi.unit_price) AS total
FROM orders o JOIN customers c ON c.id = o.customer_id LEFT JOIN order_items oi ON oi.order_id = o.id
GROUP BY o.id, c.name, o.status;

CREATE MATERIALIZED VIEW mv_sales_by_category
BUILD IMMEDIATE REFRESH COMPLETE ON DEMAND AS
SELECT p.category_id, COUNT(*) AS items, SUM(oi.qty * oi.unit_price) AS revenue
FROM order_items oi JOIN products p ON p.id = oi.product_id
GROUP BY p.category_id;

CREATE SEQUENCE seq_invoice START WITH 1000 INCREMENT BY 5 CACHE 20;

CREATE SYNONYM syn_products FOR products;

CREATE OR REPLACE FUNCTION order_total(p_order_id IN NUMBER) RETURN NUMBER IS
    t NUMBER;
BEGIN
    SELECT COALESCE(SUM(qty * unit_price), 0) INTO t FROM order_items WHERE order_id = p_order_id;
    RETURN t;
END order_total;
/

CREATE OR REPLACE PROCEDURE restock(p_id IN NUMBER, p_qty IN NUMBER) IS
BEGIN
    UPDATE products SET stock = stock + p_qty WHERE id = p_id;
END restock;
/

CREATE OR REPLACE TRIGGER trg_products_touch
BEFORE UPDATE ON products FOR EACH ROW
BEGIN
    :NEW.updated_at := SYSTIMESTAMP;
END;
/

CREATE OR REPLACE PACKAGE pkg_shop IS
    c_vat CONSTANT NUMBER := 0.21;
    FUNCTION with_vat(p_amount IN NUMBER) RETURN NUMBER;
    PROCEDURE log_msg(p_text IN VARCHAR2);
END pkg_shop;
/

CREATE OR REPLACE PACKAGE BODY pkg_shop IS
    FUNCTION with_vat(p_amount IN NUMBER) RETURN NUMBER IS
    BEGIN
        RETURN ROUND(p_amount * (1 + c_vat), 2);
    END with_vat;

    PROCEDURE log_msg(p_text IN VARCHAR2) IS
    BEGIN
        DBMS_OUTPUT.PUT_LINE(p_text);
    END log_msg;
END pkg_shop;
/

CREATE TABLE all_types (
    id           NUMBER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    c_number     NUMBER,
    c_number_ps  NUMBER(30, 10),
    c_integer    INTEGER,
    c_float      FLOAT(63),
    c_bin_float  BINARY_FLOAT,
    c_bin_double BINARY_DOUBLE,
    c_char       CHAR(5),
    c_varchar    VARCHAR2(40 CHAR),
    c_nchar      NCHAR(3),
    c_nvarchar   NVARCHAR2(20),
    c_clob       CLOB,
    c_nclob      NCLOB,
    c_blob       BLOB,
    c_raw        RAW(16),
    c_date       DATE,
    c_ts         TIMESTAMP(3),
    c_tstz       TIMESTAMP(6) WITH TIME ZONE,
    c_tsltz      TIMESTAMP WITH LOCAL TIME ZONE,
    c_iv_ym      INTERVAL YEAR(2) TO MONTH,
    c_iv_ds      INTERVAL DAY(2) TO SECOND(3)
);
