COMMIT;

CREATE TABLE big_table (
    id      NUMBER PRIMARY KEY,
    grp     NUMBER NOT NULL,
    name    VARCHAR2(64) NOT NULL,
    amount  NUMBER(12, 2) NOT NULL,
    created TIMESTAMP NOT NULL,
    payload VARCHAR2(64)
);
CREATE INDEX idx_big_grp ON big_table (grp);
INSERT INTO big_table
SELECT n, MOD(n, 100), 'name-' || n, ROUND(n * 1.37, 2), TIMESTAMP '2024-01-01 00:00:00' + NUMTODSINTERVAL(n, 'MINUTE'),
       LOWER(RAWTOHEX(STANDARD_HASH(TO_CHAR(n), 'MD5')))
FROM (SELECT LEVEL n FROM dual CONNECT BY LEVEL <= 100000);
COMMIT;
BEGIN
    DBMS_STATS.GATHER_TABLE_STATS(USER, 'BIG_TABLE');
END;
/
